*loading data from downloaded Compustat file;
data compan;
set conserv.compan;
if at^=.;
if at>0;
if incorp^='';
if incorp^='PR';
if incorp^='DC';
if exchg=11 or exchg=12 or exchg=14;
if SIC>6999 or SIC<6000;
if revt>0;
if ceq>0;
if prcc_f^=.;
if csho^=.;
if ib^=.;
cyear=fyear+1;
cusip=substr(cusip,1,8);
cik1=cik+0;
drop cik;
data comp_1;
set compan;
cik=cik1;
drop cik1;
run;

*loading data from downloaded CRSP files: monthly return and value weighted market return;
data crsp;
set conserv.crspmon;
data vwret;
set conserv.vwretd;
year=year(date);
month=month(date);
months=year*100+month;
drop year month date;
run;

*loading incorporation state data from Compact Disclosure;
data cd_inc;
set conserv.cd_inc;
cusip=substr(cusip,1,8);
if cusip^='';
run;

*loading incorporation state data from 10-K headings and IRRC;
data tk_inc;
set conserv.tk_inc;
run;

*loading incorporation state change data from Mergent Online;
data incorpo;
set conserv.incorpo;
if year_end=. then year_end=fyear-1;
run;

*assign historical incorporation data;
data comp;
set comp_7;
incorp0=stinc;
if incorp0='' then incorp0=cdinc;
if incorp0='' then incorp0=mcdinc;
if incorp0='' then incorp0=mtstinc;
if incorp0='' then incorp0=incorp;
if fyear<=year_end then incorp0=incorp_o;
drop incorp;
run;

data comp;
set comp;
incorp=incorp0;
run;

*For "Director-Liablity-Reduction Laws and Conditional Conservatism" by Sudipta Basu and Yi Liang;*******************************************************************************;
*This code creates the sample used for our regressions;**************************************************************************************************************************;
*Before runing this code, one must run Code_1 to load data from local library and assign historical incorporation states;********************************************************;

*create lagged variables;
proc sort data=comp;
by gvkey fyear;
run;
data comp1;
set comp;
lgvkey=lag(gvkey);
lfyear=lag(fyear);
lat=lag(at);
lact=lag(act);
llct=lag(lct);
lche=lag(che);
ldlc=lag(dlc);
ltxditc=lag(txditc);
lprcc_f=lag(prcc_f);
lcsho=lag(csho);
lrevt=lag(revt);
lceq=lag(ceq);
ldltt=lag(dltt);
lib=lag(ib);
if act=. then act=0;
if lct=. then lct=0;
if che=. then che=0;
if dlc=. then dlc=0;
if dltt=. then dltt=0;
if dp=. then dp=0;
if txditc=. then txditc=0;
data comp1;
set comp1;
if lgvkey=gvkey;
if lfyear=fyear-1;
run;

*next a few steps calculate annual buy-and-hold return, we first merge fiscal year end data with CRSP data;
data compan;
set compan;
keep cusip gvkey fyear fyr;
data crsp;
set crsp;
fyear=int(months/100);
run;

proc sort data=crsp;
by cusip fyear;
proc sort data=compan;
by cusip fyear;
data mer;
merge crsp compan;
by cusip fyear;
run;

data mer;
set mer;
if gvkey^=.;
if permno^=.;
month=months-100*fyear;
cyear1=fyear;
drop fyear;
run;

data mer;
set mer;
fmonth=month+(12-fyr);
if fmonth>12 then fmonth=fmonth-12;
fyear=cyear1;
if fyr>5 and month>fyr+3 then fyear=cyear1+1;
if fyr<6 and month<=fyr+3 then fyear=cyear1-1;
logret=log(1+ret);
logmret=log(1+vwretd);
run;

*calculate compound return;
proc sql;
create table returns as
select distinct cusip, fyear, sum(logret) as slogret, sum(logmret) as slogmret, count(cusip) as numobs, hsiccd from mer group by cusip, fyear;
quit;

*calculate market-adjusted return and assign bad news indicator;
data returns;
set returns;
if numobs=12;
rets=exp(slogret)-exp(slogmret);
dr=0;
if rets<0 then dr=1;
drrets=dr*rets;
gvkey1=gvkey+0;*encode gvkey to number;
run;

*set sample period (main test 1976-2002, robustness tests 1976-1995 and 1976-2013) and ensure at least one observation before and after law changes;
data compa331;
set compa33;
if fyear>=1976;
if fyear<=2002;
if minyear<lawyear;
if maxyear>lawyear;
run;***export data file to STATA for main tests and DCD tests;

*load and merge institutional ownership and dedicated ownership data with main sample;
data own;
set conserv.owner;
if INSTOWN_PERC^=.;
io=INSTOWN_PERC;
if month(rdate)=6;
fyear=year(rdate);
run;

*load dedicated ownership (following Bushee's classification) data and merge with main sample;
data ded;
set conserv.dedcount;
run;

proc sort data=own;
by cusip rdate;
proc sort data=ded;
by cusip rdate;
data dedown;
merge own ded;
by cusip rdate;

*load G-index data files (data before 1990 obtained from Martijn Cremers, after 1990 from ISS);
data gindex_89;
set conserv.gindex_89;
fyear=year;
drop year;
data gindex_90;
set conserv.gindex_90;
fyear=year;
cik1=cik+0;*convert cik into number;
drop cik year;
run;
data gindex_90;
set gindex_90;
cik=cik1;
drop cik1 ticker cn6 CONAME;
run;
*During our sample period, ISS collected data on 1990, 1993, 1995, 1998, 2000, and 2002.
*G-index of the non-collection years are assigned with the most recent prior G-index;
data gindex_91;
set gindex_90;
fyear=fyear+1;
run;
data gindex_92;
set gindex_90;
fyear=fyear+2;
if fyear=1992 or fyear=1997;
run;
data gindex_900;
set gindex_90 gindex_91 gindex_92;
run;

*load auditor data (separatly downloaded from Compustat);
data audit;
set conserv.audit;
keep gvkey fyear au;
run;

*winsorize auditor selection test control variables;
proc means data=compa4 noprint;
var lnat turnover current roa;
output out=outlier p1=bot1-bot4 p99=top1-top4; run;
data outlier;
set outlier; 
keep bot1-bot4 top1-top4;
run;
proc sql;
create table compa5 as
select * from compa4,outlier;
quit;
data compa5;
set compa5;
if lnat>top1 then lnat=top1;
if lnat<bot1 then lnat=bot1;
if turnover>top2 then turnover=top2;
if turnover<bot2 then turnover=bot2;
if current>top3 then current=top3;
if current<bot3 then current=bot3;
if roa>top4 then roa=top4;
if roa<bot4 then roa=bot4;
drop top1-top4 bot1-bot4;
run;***export data file to STATA for auditor selection tests;
